 for(const [id,b] of Object.entries(bindings)){const section=d.querySelector(b.sectionSelector),node=b.selector?section?.querySelector(b.selector):section;if(!node)throw Error('Private native binding unavailable: '+id);sections.set(b.sectionId,section);if(!sectionStyles.has(b.sectionId))sectionStyles.set(b.sectionId,section.getAttribute('style'));nodes.set(id,node);originals.set(id,{style:node.getAttribute('style'),html:node.innerHTML});section.dataset.conjureNative='true';section.dataset.conjureSlot='native';section.dataset.section=b.sectionId;section.classList.add('manifest-section');}
